def find_length(s):
    import sys
    sys.setrecursionlimit(10000)
    max_diff = 0
    count = 0
    hash_map = {0: -1}
    for i in range(len(s)):
        if s[i] == '1':
            count += 1
        else:
            count -= 1
        if count in hash_map:
            max_diff = max(max_diff, i - hash_map[count])
        else:
            hash_map[count] = i
    return max_diff
